q2:
SELECT DISTINCT *
FROM (
  SELECT * FROM R AS X WHERE X.X > 50
  UNION ALL
  SELECT * FROM R AS Y WHERE Y.X < 200
) AS T;

SELECT * FROM R1 AS X, R2 AS Y
UNION ALL
SELECT * FROM R1 AS X, R3 AS Y;

