counterexample:
INSERT INTO CARRIERS (CID, NAME) VALUES (1, 1);
WITH RECURSIVE counter(n) AS (
  SELECT 1
  UNION ALL
  SELECT n+1 FROM counter WHERE n < 1001
)
INSERT INTO FLIGHTS (FID, YEAR, MONTH_ID, DAY_OF_MONTH, CARRIER_ID)
SELECT n, 2020, CASE WHEN n <= 1000 THEN 1 ELSE 2 END, 1, 1 FROM counter;

